      await chooseReward(p, 'בוסט');

      await p.route('**/rest/v1/**', (route) =>
        ['GET', 'HEAD', 'OPTIONS'].includes(route.request().method()) ? route.continue() : route.abort('internetdisconnected'),
      );
      await claimButton(p).click();
      await expect(p.getByText('לא הצלחנו לממש את הפרס. נסו שוב')).toBeVisible({ timeout: 15_000 });
